package admin

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"time"

	"github.com/danielgtaylor/huma/v2"
	"go.uber.org/zap"

	"github.com/onhotpath/tempogate/keys"
)

const (
	// SigningKeysPath and SigningKeyRetirePath are exported for the same
	// reason as KeysPath: tests and docs reference the registered strings.
	SigningKeysPath      = "/admin/signing-keys"
	SigningKeyRetirePath = "/admin/signing-keys/{kid}/retire"
)

// Keyring is the signing-key aggregate as the admin routes need it.
// *keys.Keys satisfies it; Keypairs reads through to the store so keys
// generated by another process show up without waiting for a reload.
type Keyring interface {
	Keypairs(ctx context.Context) ([]keys.Keypair, error)
	Retire(ctx context.Context, kid string) (keys.Keypair, error)
}

// SigningKeys serves the signing-key list and the retire operation.
// Retirement is the only kill switch Temporal honours: once a retired kid's
// grace has elapsed it leaves JWKS, and every token it signed stops verifying.
type SigningKeys struct {
	ring   Keyring
	logger *zap.Logger
}

// SigningKeysOption configures *SigningKeys.
type SigningKeysOption func(*SigningKeys)

// WithSigningKeysLogger sets the logger the audit trail is written to.
//
// Panics on nil for the same reason as WithLogger.
func WithSigningKeysLogger(l *zap.Logger) SigningKeysOption {
	if l == nil {
		panic("admin: WithSigningKeysLogger requires a non-nil logger")
	}
	return func(h *SigningKeys) { h.logger = l }
}

// NewSigningKeys panics on a nil keyring so a wiring bug fails at startup
// rather than on the first request.
func NewSigningKeys(ring Keyring, opts ...SigningKeysOption) *SigningKeys {
	if ring == nil {
		panic("admin: NewSigningKeys requires a non-nil keyring")
	}
	h := &SigningKeys{ring: ring, logger: zap.NewNop()}
	for _, o := range opts {
		o(h)
	}
	return h
}

type signingKeyView struct {
	Kid       string     `json:"kid"`
	Alg       string     `json:"alg"`
	CreatedAt time.Time  `json:"created_at"`
	RetiredAt *time.Time `json:"retired_at,omitempty" doc:"set once retired; the key leaves JWKS KEYS_RETIREMENT_GRACE later"`
	Active    bool       `json:"active" doc:"true for the one key that signs new tokens"`
}

type signingKeyListOutput struct {
	Body struct {
		Items []signingKeyView `json:"items"`
	}
}

type signingKeyRetireInput struct {
	Kid string `path:"kid"`
}

type signingKeyRetireOutput struct {
	Body signingKeyView
}

func (h *SigningKeys) Register(api huma.API) {
	huma.Register(api, huma.Operation{
		OperationID: "admin-list-signing-keys",
		Security:    adminSecurity,
		Method:      http.MethodGet,
		Path:        SigningKeysPath,
		Summary:     "List JWT signing keys, oldest first",
		Tags:        []string{"admin"},
	}, h.list)

	huma.Register(api, huma.Operation{
		OperationID: "admin-retire-signing-key",
		Security:    adminSecurity,
		Method:      http.MethodPost,
		Path:        SigningKeyRetirePath,
		Summary:     "Retire a signing key (idempotent; refuses the only active key)",
		Description: "The key stops signing at once and leaves JWKS after KEYS_RETIREMENT_GRACE; " +
			"from then on every token it signed, integration keys included, stops verifying.",
		Tags: []string{"admin"},
	}, h.retire)
}

func (h *SigningKeys) list(ctx context.Context, _ *struct{}) (*signingKeyListOutput, error) {
	kps, err := h.ring.Keypairs(ctx)
	if err != nil {
		return nil, fmt.Errorf("admin: list signing keys: %w", err)
	}
	active, _ := keys.Active(kps)
	out := &signingKeyListOutput{}
	out.Body.Items = make([]signingKeyView, 0, len(kps))
	for _, kp := range kps {
		out.Body.Items = append(out.Body.Items, signingKeyViewOf(kp, kp.Kid == active.Kid))
	}
	return out, nil
}

func (h *SigningKeys) retire(ctx context.Context, in *signingKeyRetireInput) (*signingKeyRetireOutput, error) {
	kp, err := h.ring.Retire(ctx, in.Kid)
	h.audit(ctx, in.Kid, err)
	switch {
	case err == nil:
		// A key that retired successfully is never the active one.
		return &signingKeyRetireOutput{Body: signingKeyViewOf(kp, false)}, nil
	case errors.Is(err, keys.ErrKeypairNotFound):
		return nil, huma.Error404NotFound("signing key not found")
	case errors.Is(err, keys.ErrLastActiveKeypair):
		return nil, huma.Error409Conflict("this is the only active signing key; run `tempogate keys generate --force` first")
	default:
		return nil, fmt.Errorf("admin: retire signing key: %w", err)
	}
}

func signingKeyViewOf(kp keys.Keypair, active bool) signingKeyView {
	return signingKeyView{
		Kid:       kp.Kid,
		Alg:       kp.Alg,
		CreatedAt: kp.CreatedAt,
		RetiredAt: kp.RetiredAt,
		Active:    active,
	}
}

// audit writes one line per retire attempt that passed the guard.
func (h *SigningKeys) audit(ctx context.Context, kid string, err error) {
	outcome := "success"
	switch {
	case err == nil:
	case errors.Is(err, keys.ErrKeypairNotFound):
		outcome = "not_found"
	case errors.Is(err, keys.ErrLastActiveKeypair):
		outcome = "conflict"
	default:
		outcome = "error"
	}
	c := callerFrom(ctx)
	h.logger.Info("admin audit",
		zap.String("action", "retire_signing_key"),
		zap.String("outcome", outcome),
		zap.String("kid", kid),
		zap.String("caller", c.fingerprint),
		zap.String("remote_addr", c.remoteAddr),
	)
}
